#include <iostream>
#include <memory>
class Quote {
    struct Impl;
    std::unique_ptr<Impl> p;
public:
    explicit Quote(int);
    ~Quote();
    int price() const;
};
struct Quote::Impl { int value; };
Quote::Quote(int x): p(std::make_unique<Impl>(Impl{x})) {}
Quote::~Quote() = default;
int Quote::price() const { return p->value; }
template<class D> struct Base {
    int run(int x) const { return static_cast<const D*>(this)->apply(x); }
};
struct Twice: Base<Twice> { int apply(int x) const { return 2*x; } };
struct OneTick { static int apply(int x) { return x+1; } };
template<class Policy> struct Engine { int run(int x) const { return Policy::apply(x); } };
int main() {
    std::cout << Quote(7).price() << '\n';
    std::cout << Twice{}.run(7) << '\n';
    std::cout << Engine<OneTick>{}.run(7) << '\n';
}
